 p.update(review_stage='design_sources_reviewed',relevance='design_bearing',design_contributions=['reused_design','uncertain'],catalog_eligibility='unresolved',access='main_and_SI_reprints_available; publisher_original_403',rationale=note,reviewer='Codex visual main/SI page review',run_id=rid,date=L.DATE,temporal_scope='pre2020_verified',date_evidence={'date':'2018-11-06','source':me,'primary_verified':True,'meaning':'Accepted manuscript online; first publicly online article version printed on journalp916','version_of_record_online':'2018-12-11','issue_date':'2019-01-14','issue_date_source':ce},unresolved_questions=qs)
